actions.script:
def owner = ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN')
shopAccessRestricted = !owner && ['ZENITH_CASHIER','ZENITH_STORE_MGR','ZENITH_MULTI_SHOP_MANAGER'].any { ec.user.isInGroup(it) }
activeShopId = shopAccessRestricted ? '__NONE__' : null
activeShopName = null; isAllShops = !shopAccessRestricted
shopCount = 0; hasMultiShop = false; shopListJson = '[]'; shopList = []
terminalIds = null; sessionIds = null

def org = ec.service.sync().name('zenith.base.RoleAccessServices.get#RoleOrganization')
    .disableAuthz().call()?.organizationPartyId
if (!org || org == '_NA_') { return }

boolean _dz = ec.artifactExecution.disableAuthz()
try {
    def shops = ec.entity.find("mantle.facility.Facility")
            .condition("ownerPartyId", org)
            .condition("facilityTypeEnumId", "FcTpRetailStore")
            .useCache(true).list()
    // Once shops are registered, their linked facilities are authoritative. An
    // unused onboarding stock facility is not an additional customer-facing shop.
    // Older organizations with no Store rows keep their existing facility list.
    def registered = ec.entity.find('zenith.erp.stores.Store')
            .condition('organizationPartyId', org).useCache(true).list()
    if (registered) {
        def registeredIds = registered.collect { it.facilityId }.findAll { it } as Set
        shops = shops.findAll { registeredIds.contains(it.facilityId) }
    }
    if (!owner) {
        def policy = ec.entity.find('zenith.erp.base.OrganizationUserShopAccess')
            .condition('organizationPartyId',org).condition('userId',ec.user.userId).useCache(true).one()
        def assignment = ec.entity.find('zenith.erp.pos.PosTerminalAssignment')
            .condition('organizationPartyId',org).condition('userId',ec.user.userId).useCache(true).one()
        shopAccessRestricted = shopAccessRestricted || policy != null || assignment != null
        if (!shopAccessRestricted && ec.user.userGroupIdSet.any { it.startsWith('ZENITH_ORG_') }) {
            def roleScope = ec.service.sync().name('zenith.base.RoleAccessServices.get#AssignedRoleScope').disableAuthz().call()
            shopAccessRestricted = !!roleScope.selections?.pos
        }
        if (shopAccessRestricted) {
            def shopIds = policy ? new groovy.json.JsonSlurper().parseText(policy.shopIdsJson ?: '[]') : []
            if (!policy && assignment) {
                def terminal = ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',assignment.terminalId)
                    .condition('organizationPartyId',org).condition('isActive','Y').useCache(true).one()
                if (terminal?.organizationPartyId == org && terminal.facilityId) shopIds = [terminal.facilityId]
            }
            shops = shops.findAll { it.facilityId in shopIds }
            activeShopId = '__NONE__'
            isAllShops = false
        }
    }
    shops = shops ? shops.sort { (it.facilityName ?: it.facilityId) } : []
    shopCount = shops.size()
    hasMultiShop = shopCount >= 2
    shopList = shops.collect { [id: it.facilityId, name: (it.facilityName ?: it.facilityId)] }
    shopListJson = groovy.json.JsonOutput.toJson(shopList)

    // candidate = explicit override else the stored preference
    def cand = facilityId ?: ec.user.getPreference("ACTIVE_SHOP")
    def match = cand ? shops.find { it.facilityId == cand } : null
    if (!match && shopAccessRestricted && shops) match = shops.first()
    if (match) {
        activeShopId = match.facilityId
        activeShopName = match.facilityName ?: match.facilityId
        isAllShops = false
    }

    if (includePosScope && activeShopId) {
        def terms = ec.entity.find("zenith.erp.pos.PosTerminal")
                .condition("organizationPartyId", org)
                .condition("facilityId", activeShopId)
                .useCache(true).list()
        terminalIds = terms ? terms.collect { it.terminalId }.unique() : []
        if (terminalIds) {
            def ss = ec.entity.find("zenith.erp.pos.PosSession")
                    .condition("organizationPartyId", org)
                    .condition("terminalId", "in", terminalIds)
                    .useCache(true).list()
            sessionIds = ss ? ss.collect { it.sessionId }.unique() : ['__NONE__']
        } else {
            sessionIds = ['__NONE__']   // shop has no counter yet => matches no sales
        }
    }
} finally { if (!_dz) ec.artifactExecution.enableAuthz() }
